  refresh_token: account.refresh_token,
});

async function main() {
  // Get fresh token
  const { credentials: newCreds } = await oauth2Client.refreshAccessToken();
  console.log('Refreshed scopes:', newCreds.scope);

  // Try using googleapis with the token directly
  // cloud-platform scope might not work for Calendar, let me try the REST API approach
  const https = require('https');

  const accessToken = newCreds.access_token;

  // Try Calendar API with the cloud-platform token
  const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=2026-01-06T00:00:00Z&timeMax=2026-01-10T00:00:00Z&singleEvents=true&orderBy=startTime`;

  const response = await fetch(url, {
    headers: {
      'Authorization': `Bearer ${accessToken}`,
      'Accept': 'application/json'
    }
  });

  const data = await response.json();
  console.log('Status:', response.status);
  console.log('Response:', JSON.stringify(data, null, 2));
}

