input.command:
# The token in tokens.json starts with ya29.c which is a GCE service account token format
# The GCE metadata server might have had calendar scopes configured at some point
# but now only has monitoring/logging scopes.

# Let me try: maybe these tokens.json files were recently generated and the 
# access tokens are still valid if I use them correctly with the Node.js library
# without trying to refresh

node -e "
const { google } = require('googleapis');
const tokens = require('/root/auth/calendar/tokens.json');
const account = tokens.accounts[tokens.defaultAccount];

// Try using the token directly without any OAuth2 client
// Just use the raw access token
const fetch = require('node:https');
const url = 'https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=2026-01-06T00:00:00Z&timeMax=2026-01-10T00:00:00Z&singleEvents=true&orderBy=startTime';

// Check token info first
const tokenInfoUrl = 'https://oauth2.googleapis.com/tokeninfo?access_token=' + encodeURIComponent(account.access_token);
fetch.get(tokenInfoUrl, (res) => {
  let data = '';
  res.on('data', chunk => data += chunk);
  res.on('end', () => {
    console.log('Token info status:', res.statusCode);
    try {
      const info = JSON.parse(data);
      console.log('Token info:', JSON.stringify(info, null, 2));
    } catch(e) {
      console.log('Raw response:', data.substring(0, 200));
    }
  });
});
"

